INSERT INTO products (name, slug, tagline, category, summary, description, status, website_url, cta_label, brand_color, accent_color, gallery, content, is_published, sort_order) VALUES ('Matschool', 'matschool', 'Learn to code, one lesson at a time', 'Online Learning Platform', 'Free coding tutorials, a live code editor, quizzes, competitions and certificates for students and working professionals.', 'Matschool is a free platform for learning to code. Pick a subject, learn one lesson at a time, run the code in the built-in editor, pass a quiz after each tutorial, and collect a certificate as you progress.', 'live', 'https://matschool.in/', 'Visit Matschool', '#ea580c', '#facc15', '[]', '{"highlights":[{"value":"Free","label":"to start, no sign-up needed to look around"},{"value":"7","label":"subjects including HTML, CSS, JavaScript and Python"},{"value":"Live","label":"code editor that runs in the browser"},{"value":"Certs","label":"earned as you complete subjects"}],"problems":[],"features":[{"title":"Free tutorials","text":"Step by step lessons for HTML, CSS, JavaScript, PHP, Python, SQL and Git."},{"title":"Live code editor","text":"Write and run your code in the browser while you learn, with a live result beside it."},{"title":"Quizzes","text":"A short quiz ends each tutorial, so you know what has actually stuck."},{"title":"Progress and leaderboard","text":"Track your lessons and see where you stand among other learners."},{"title":"Certificates","text":"Collect a certificate when you finish a subject."},{"title":"Competitions","text":"Join coding contests and challenges, with upcoming and past events listed."}],"steps":[{"title":"Create a free account","text":"Sign up in a minute to save your progress."},{"title":"Pick a subject","text":"Choose a subject and follow the lessons in order."},{"title":"Learn one lesson at a time","text":"Read the lesson, run the code and mark it complete."},{"title":"Test yourself","text":"Pass each quiz and collect your certificate at the end."}],"audience":["Students learning to code","Working professionals upskilling","Anyone who wants to join coding contests"],"plans":[],"faqs":[{"question":"Is Matschool free?","answer":"Yes. You can start learning for free, and you can look around without signing up."},{"question":"How do certificates work?","answer":"Complete a subject and pass its quizzes to earn a certificate."},{"question":"Can I run the code examples?","answer":"Yes. The built-in editor runs your code in the browser."}]}', 1, 5);
